const DirectSms = registerPlugin("DirectSms");
const NativeBackup = registerPlugin("NativeBackup");
const DB_NAME = "karobaar-manager";
const DB_VERSION = 9;
const STORE_NAMES = ["products","purchases","sales","customers","expenses","payments","stock_adjustments","sales_returns","suppliers","supplier_payments","business_profile","inventory_batches","sms_messages"];
const money = n => "Rs. " + Number(n || 0).toLocaleString("en-PK",{maximumFractionDigits:2});
const localISO = d => {const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return `${y}-${m}-${day}`;};
const today = () => localISO(new Date());
const fmtDate = d => d ? new Date(d+"T00:00:00").toLocaleDateString("en-PK",{day:"numeric",month:"short",year:"numeric"}) : "—";
const uid = () => crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36)+Math.random().toString(36).slice(2);
let db, currentPage = "dashboard", chartRange = "week", reportRange = "month";
const $ = s => document.querySelector(s);

function openDB(){return new Promise((resolve,reject)=>{if(!("indexedDB" in window))return reject(new Error("IndexedDB is unavailable in this app context"));const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;for(const name of STORE_NAMES){if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:"id"});}};req.onblocked=()=>reject(new Error("Database upgrade is blocked by another open app tab. Close other Karobaar Manager tabs and reopen."));req.onsuccess=()=>{const d=req.result;d.onversionchange=()=>d.close();resolve(d);};req.onerror=()=>reject(req.error||new Error("IndexedDB open failed"));});}
function all(store){return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function put(store,value){return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).put(value);tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);});}
function remove(store,id){return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function data(){const out={};for(const s of STORE_NAMES)out[s]=await all(s);return out;}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2600);}
function modal(title,html){$("#modalTitle").textContent=title;$("#modalBody").innerHTML=html;$("#modal").hidden=false;}
function closeModal(){stopBarcodeScanner();$("#modal").hidden=true;}
function within(date,days){const d=new Date(date+"T00:00:00"),n=new Date();return d>=new Date(n.getFullYear(),n.getMonth(),n.getDate()-days+1);}
function dateFilter(items,range){if(range==="all")return items;const days=range==="week"?7:range==="month"?30:365;return items.filter(x=>within(x.date,days));}
let renderSequence=0;async function render(){const sequence=++renderSequence,page=currentPage;const d=await data();if(sequence!==renderSequence||page!==currentPage)return;$("#todayLabel").textContent=new Date().toLocaleDateString("en-PK",{weekday:"long",day:"numeric",month:"long",year:"numeric"});const titles={dashboard:"Dashboard",sales:"Sales",products:"Products & stock",customers:"Customers",purchases:"Purchases",expenses:"Expenses",reports:"Reports",stock:"Stock adjustments",returns:"Sales returns",suppliers:"Suppliers",settings:"Backup & settings"};$("#pageTitle").textContent=titles[page];document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===page));const pages={dashboard:dashboardPage,sales:salesPage,products:productsPage,customers:customersPage,purchases:purchasesPage,expenses:expensesPage,reports:reportsPage,stock:stockAdjustmentsPage,returns:salesReturnsPage,suppliers:suppliersPage,settings:settingsPage};$("#pageContent").innerHTML=pages[page](d);}
function pageIntro(title,sub,action,label){const guides={"Products & stock":"Add each item once. Stock increases when you record a purchase and decreases when you make a sale.","Sales history":"Tap New sale, choose the customer and items, enter weight or quantity, then save the bill.","Customers":"Save customer names here. Choose a customer during a sale to keep their account and outstanding balance.","Purchases":"When new goods arrive, enter the quantity and the full bill amount. The app calculates the cost per unit.","Expenses":"Record shop expenses such as rent, electricity and transport.","Reports":"Choose a date range to review sales, purchases, expenses and profit.","Stock adjustments":"Use this only to correct stock when physical quantity differs from the app.","Sales returns":"Choose a previous sale and record the quantity returned.","Suppliers":"Save the people or businesses you buy goods from.","Backup & settings":"Download a backup regularly. Keep a copy before restoring any file."};const guide=guides[title]||"Choose a task. Your changes are saved on this device.";return `<div class="welcome-row"><div><h2>${title}</h2><div class="subtext">${sub}</div><details class="simple-help"><summary>How do I use this?</summary><p>${guide}</p></details></div>${action?`<button class="button" data-action="${action}">＋ ${label}</button>`:""}</div>`;}
