 const todayKey=today(),todaySales=d.sales.filter(x=>x.date===todayKey),todayExpenses=d.expenses.filter(x=>x.date===todayKey),todayRevenue=sum(todaySales,x=>Number(x.total||0)),todayCost=sum(todayExpenses,x=>Number(x.amount||0)),lowStock=d.products.filter(p=>Number(p.stock||0)<=Number(p.minStock||0)).length,outstanding=sum(d.customers,c=>Math.max(0,customerBalance(d,c).balance)),recent=groupSalesByInvoice(d.sales,d.sales_returns).sort((a,b)=>b.createdAt-a.createdAt).slice(0,5);
