async function downloadBackup(){try{const d=await data();const payload={app:"Karobaar Manager",formatVersion:1,exportedAt:new Date().toISOString(),data:d};const content=JSON.stringify(payload,null,2),filename="karobaar-backup-"+today()+".json";const status=$("#backupStatus");if(Capacitor.isNativePlatform()){const result=await NativeBackup.saveBackup({filename,content});if(!result||!result.saved)throw new Error("Android did not confirm that the backup was saved");if(status)status.textContent="Backup saved in Downloads/Karobaar Manager/"+filename;toast("Backup saved to Downloads");return;}const blob=new Blob([content],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);if(status)status.textContent="Backup download started. Check your Downloads folder.";toast("Backup download started");}catch(error){const message=error.message||"Backup could not be prepared";const status=$("#backupStatus");if(status)status.textContent=message;toast(message);}}
