async function sendInvoiceSms(customer,records,invoiceNo,date,grandTotal,paid){
 if(!customer||!String(customer.phone||"").trim())return {sent:false,reason:"Customer phone number is missing"};
 if(!Capacitor.isNativePlatform()||Capacitor.getPlatform()!=="android")return {sent:false,reason:"Automatic SMS is available in the Android APK only"};
 const itemLines=records.map(x=>x.productName+" "+Number(x.qty).toLocaleString("en-PK",{maximumFractionDigits:3})+" "+(x.unit||"")+" = "+money(x.total));
 const balance=Math.max(0,Number(grandTotal||0)-Number(paid||0));
 const message=["Karobaar Manager - Sales Bill", "Invoice: "+invoiceNo, "Date: "+fmtDate(date), ...itemLines, "Total: "+money(grandTotal), "Received: "+money(paid), "Balance due: "+money(balance)].join("\n");
 const log={id:uid(),customerId:customer.id,customerName:customer.name,phone:customer.phone,message,status:"Sending",date,createdAt:Date.now()};
 try{
  const result=await DirectSms.send({phone:String(customer.phone).trim(),message});
  log.status="Submitted to SIM (delivery not confirmed)";
  log.parts=Number(result.parts||1);
  await put("sms_messages",log);
  return {sent:true,parts:log.parts};
 }catch(error){
  log.status="Failed: "+String(error?.message||error||"SMS failed");
  try{await put("sms_messages",log);}catch(saveError){console.warn("Could not save invoice SMS status",saveError);}
  return {sent:false,reason:String(error?.message||"SMS could not be sent")};
 }
}
